source='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    counts = {}
    for r, c in points:
        counts[r] = counts.get(r, 0) + 1
    spine_row = max(counts, key=counts.get)
    spine_cols = [c for r, c in points if r == spine_row]
    left, right = min(spine_cols), max(spine_cols)
    for c in range(left, right + 1):
        if out[spine_row][c] == 0:
            out[spine_row][c] = 3
    for r, c in points:
        if r == spine_row:
            continue
        step = 1 if spine_row > r else -1
        for rr in range(r + step, spine_row + step, step):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
'''
